"""Targeted geometry update for the editable upholstered bed generator.

The original generator is gzip-packed to keep the repository compact. This patch
is deliberately isolated in plain Python so the bed design remains reviewable.
"""
from __future__ import annotations

OLD_GEOMETRY = "# ----------------------- PILLOWS AND HEADBOARD -----------------------\n# Two substantial sleep pillows plus smaller slate accent cushions, each independently modeled.\nfor side in (-1,1):\n    x=side*.49\n    superellipsoid(f'Sleep_pillow_{side}',(x,1.095,-1.115),(.52,.175,.335),'sheet',.48,72,44,taper=.34)\n    # Fine seam along the pillow's visible front crown.\n    curve_tube(f'Sleep_pillow_piping_{side}',[(x+u,1.19,-1.405+.025*math.cos(u*2.2)) for u in np.linspace(-.43,.43,28)],.0024,'pillow')\nfor side in (-1,1):\n    x=side*.285\n    superellipsoid(f'Slate_accent_cushion_{side}',(x,1.215,-.795),(.37,.155,.245),'pillow',.50,64,40,taper=.26)\n# A compact lumbar cushion in muted steel blue to layer the pillows.\nsuperellipsoid('Lumbar_cushion',(0,1.245,-.57),(.46,.135,.155),'throw',.53,64,36,taper=.30)\n\n# Structural headboard shell and seven individual, vertically channeled upholstered pads.\n# The channels have eased shoulders, a softly bowed face, and visible shadow seams.\nsuperellipsoid('Headboard_back_shell',(0,1.185,-1.575),(1.29,.925,.115),'charcoal2',.50,88,52)\nsuperellipsoid('Headboard_top_rail',(0,2.035,-1.475),(1.245,.085,.125),'charcoal',.55,72,36)\nfor i in range(7):\n    x=(i-3)*.354\n    superellipsoid(f'Headboard_channel_{i+1:02d}',(x,1.275,-1.435),(.174,.735,.112),'charcoal',.50,64,44,taper=.18)\n    # Delicate stitched inset down the centre of every padded section.\n    curve_tube(f'Headboard_channel_stitch_{i+1:02d}',[(x,0.72+j*.043,-1.326+.006*math.cos(j*.18)) for j in range(29)],.00115,'charcoal2')\n# Side wings roll forward just a little, framing the upholstered centre panel.\nfor side in (-1,1):\n    superellipsoid(f'Headboard_side_bolster_{side}',(side*1.205,1.255,-1.415),(.105,.77,.135),'charcoal2',.50,56,36)\n# Rear support brackets are hidden in normal view but add a credible connection to the frame.\nfor side in (-1,1):\n    boxsoft(f'Headboard_mount_{side}',(side*.92,.74,-1.53),(.105,.48,.13),'underside',.40)\n"

NEW_GEOMETRY = "# ----------------------- PILLOWS AND HEADBOARD -----------------------\n# Two substantial sleep pillows plus smaller slate accent cushions, each independently modeled.\nfor side in (-1,1):\n    x=side*.49\n    superellipsoid(f'Sleep_pillow_{side}',(x,1.095,-1.115),(.52,.175,.335),'sheet',.48,72,44,taper=.34)\n    # Fine seam along the pillow's visible front crown.\n    curve_tube(f'Sleep_pillow_piping_{side}',[(x+u,1.19,-1.405+.025*math.cos(u*2.2)) for u in np.linspace(-.43,.43,28)],.0024,'pillow')\nfor side in (-1,1):\n    x=side*.285\n    superellipsoid(f'Slate_accent_cushion_{side}',(x,1.215,-.795),(.37,.155,.245),'pillow',.50,64,40,taper=.26)\n# A compact lumbar cushion in muted steel blue to layer the pillows.\nsuperellipsoid('Lumbar_cushion',(0,1.245,-.57),(.46,.135,.155),'throw',.53,64,36,taper=.30)\n\n# ----------------------- DIAMOND-TUFTED LED HEADBOARD ONLY -----------------------\n# The platform, mattress, bedding, original sleep pillows and decorative cushions\n# remain the original generator geometry. Only the old channel headboard is\n# replaced with a softly rounded diamond-tufted upholstered panel.\nsuperellipsoid(\n    'Headboard_outer_shell',(0,1.185,-1.575),\n    (1.29,.925,.115),'charcoal2',.56,112,72\n)\nsuperellipsoid(\n    'Headboard_tufted_backing',(0,1.245,-1.415),\n    (1.205,.79,.13),'charcoal',.56,112,72\n)\nsuperellipsoid(\n    'Headboard_top_rail',(0,2.035,-1.475),\n    (1.245,.085,.125),'charcoal2',.55,72,36\n)\n\n# Rounded upholstered lozenges form the deep diamond pattern seen in the\n# reference headboard. Each cushion is a separate mesh with soft shoulders.\nfor row in range(4):\n    y=.735+row*.345\n    row_shift=.205 if row%2 else 0.0\n    for column in range(5):\n        x=(column-2)*.41+row_shift\n        diamond_center=np.array([x,y,-1.225],dtype=float)\n        diamond=superellipsoid(\n            f'Headboard_diamond_tuft_{row+1:02d}_{column+1:02d}',\n            tuple(diamond_center),(.205,.155,.075),\n            'charcoal',.50,64,44,taper=.06\n        )\n        diamond.apply_transform(trimesh.transformations.rotation_matrix(\n            math.radians(45.0),(0.0,0.0,1.0),point=diamond_center\n        ))\n\n# Small recessed pull-buttons sit at the meeting points between the padded\n# lozenges, creating the characteristic deep diamond-tufted finish.\nfor row in range(3):\n    y=.905+row*.345\n    row_shift=.205 if row%2 else 0.0\n    for column in range(6):\n        x=-1.025+column*.41+row_shift\n        superellipsoid(\n            f'Headboard_tuft_button_{row+1:02d}_{column+1:02d}',\n            (x,y,-1.135),(.024,.024,.016),'sheet',.52,32,20\n        )\n\n# Satin-silver trim outlines the headboard panel. A separate emissive reveal\n# follows the inside edge so the existing six-preset LED remote can control it.\nheadboard_silver_outline=[\n    (-1.145,.39,-1.125),(-1.145,1.965,-1.125),\n    (1.145,1.965,-1.125),(1.145,.39,-1.125),\n    (-1.145,.39,-1.125)\n]\ncurve_tube('Headboard_silver_grey_perimeter',headboard_silver_outline,.020,'sheet')\nheadboard_led_outline=[\n    (-1.095,.455,-1.132),(-1.095,1.90,-1.132),\n    (1.095,1.90,-1.132),(1.095,.455,-1.132),\n    (-1.095,.455,-1.132)\n]\ncurve_tube('Headboard_blue_violet_LED_reveal',headboard_led_outline,.009,'throw')\n\n# Keep the original padded side wings and hidden mounting brackets; they are\n# structural parts of the headboard, not changes to the bed frame.\nfor side in (-1,1):\n    superellipsoid(\n        f'Headboard_side_bolster_{side}',\n        (side*1.205,1.255,-1.415),(.105,.77,.135),\n        'charcoal2',.50,56,36\n    )\nfor side in (-1,1):\n    boxsoft(f'Headboard_mount_{side}',(side*.92,.74,-1.53),(.105,.48,.13),'underside',.40)\n"

def patch_bed_geometry(source: str) -> str:
    if source.count(OLD_GEOMETRY) != 1:
        raise RuntimeError(
            "Bed geometry patch did not find exactly one original pillow/headboard block; "
            "refusing to generate an unexpected model."
        )
    source = source.replace(OLD_GEOMETRY, NEW_GEOMETRY, 1)
    old_design = "'design':'Diamond-tufted upholstered LED headboard with satin-silver trim and controllable perimeter lighting; original bed frame, mattress and bedding retained',"
    new_design = "'design':'Black diamond-tufted LED headboard and matching footboard, silver-grey perimeter trim, quilted gusset pillows, graphite duvet and midnight-blue throw',"
    if source.count(old_design) != 1:
        raise RuntimeError("Bed metadata design marker changed; update the design patch.")
    return source.replace(old_design, new_design, 1)
